def unique_paths_brute(i, j, m, n):
    if i == m - 1 and j == n - 1:
        return 1
    if i >= m or j >= n:
        return 0
    return unique_paths_brute(i + 1, j, m, n) + unique_paths_brute(i, j + 1, m, n)   # try BOTH moves

