def unique_paths(m, n):
    dp = [[1] * n for _ in range(m)]                      # first row/col all 1
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i - 1][j] + dp[i][j - 1]           # sum of top and left neighbors
    return dp[m - 1][n - 1]

