public class Main {
    static int uniquePaths(int m, int n) {
        int[][] dp = new int[m][n];
        for (int i = 0; i < m; i++) dp[i][0] = 1;                  // first column
        for (int j = 0; j < n; j++) dp[0][j] = 1;                  // first row
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1];               // sum of top and left neighbors
            }
        }
        return dp[m - 1][n - 1];
    }
}

